            void track_line(
                  int8_t* buffer,
                             ElementRefData elem_ref_data,
                             ParticlesData particles,
                             int num_turns,
                             int ele_start,
                             int num_ele_track,
                             int flag_end_turn_actions,
                             int flag_reset_s_at_end_turn,
                             int flag_monitor,
                             int num_ele_line,
                             double line_length,
                  int8_t* buffer_tbt_monitor,
                             int64_t offset_tbt_monitor,
                  int8_t* buffer_multi_element_monitor,
                             int64_t offset_multi_element_monitor,
                  int8_t* io_buffer,
                             uint64_t track_flags
                             ){

            #define CONTEXT_OPENMP  //only_for_context cpu_openmp
            #ifdef CONTEXT_OPENMP
                const int64_t capacity = ParticlesData_get__capacity(particles);
                const int num_threads = omp_get_max_threads();

                #ifndef XT_OMP_SKIP_REORGANIZE
                    const int64_t num_particles_to_track = ParticlesData_get__num_active_particles(particles);

                    {
                        LocalParticle lpart;
                        lpart.io_buffer = io_buffer;
                        Particles_to_LocalParticle(particles, &lpart, 0, capacity);
                        check_is_active(&lpart);
                        count_reorganized_particles(&lpart);
                        LocalParticle_to_Particles(&lpart, particles, 0, capacity);
                    }
                #else // When we skip reorganize, we cannot just batch active particles
                    const int64_t num_particles_to_track = capacity;
                #endif

                const int64_t chunk_size = (num_particles_to_track + num_threads - 1)/num_threads; // ceil division
            #endif // CONTEXT_OPENMP

            #pragma omp parallel for                                                           //only_for_context cpu_openmp
            for (int chunk = 0; chunk < num_threads; chunk++) {                                //only_for_context cpu_openmp
            int64_t part_id = chunk * chunk_size;                                              //only_for_context cpu_openmp
            int64_t end_id = (chunk + 1) * chunk_size;                                         //only_for_context cpu_openmp
            if (end_id > num_particles_to_track) end_id = num_particles_to_track;              //only_for_context cpu_openmp

//            int64_t part_id = 0;                                      //only_for_context cpu_serial
//            int64_t part_id = blockDim.x * blockIdx.x + threadIdx.x;  //only_for_context cuda
//            int64_t part_id = get_global_id(0);                       //only_for_context opencl
//            int64_t end_id = 0; // unused outside of openmp           //only_for_context cpu_serial cuda opencl

            LocalParticle lpart;
            lpart.io_buffer = io_buffer;
            lpart.track_flags = track_flags;
            lpart.line_length = line_length;

              int8_t* tbt_mon_pointer =
                            buffer_tbt_monitor + offset_tbt_monitor;
            ParticlesMonitorData tbt_monitor =
                            (ParticlesMonitorData) tbt_mon_pointer;

              int8_t* multi_elem_mon_pointer =
                    buffer_multi_element_monitor + offset_multi_element_monitor;
            MultiElementMonitorData tbt_multi_elem_monitor =
                    (MultiElementMonitorData) multi_elem_mon_pointer;

            int64_t part_capacity = ParticlesData_get__capacity(particles);
            if (part_id<part_capacity){
            Particles_to_LocalParticle(particles, &lpart, part_id, end_id);

            int64_t isactive = check_is_active(&lpart);

            for (int64_t iturn=0; iturn<num_turns; iturn++){

                if (!isactive){
                    break;
                }

                int64_t const ele_stop = ele_start + num_ele_track;

                int64_t elem_idx, increm;
                if (LocalParticle_check_track_flag(&lpart, XS_FLAG_BACKTRACK)) {
                    elem_idx = ele_stop - 1;
                    increm = -1;
                    if (flag_end_turn_actions>0){
                        increment_at_turn_backtrack(&lpart, flag_reset_s_at_end_turn,
                                                    line_length, num_ele_line);
                    }
                }
                else{
                    if (flag_monitor==1){
                        ParticlesMonitor_track_local_particle(tbt_monitor, &lpart);
                    }
                    elem_idx = ele_start;
                    increm = 1;
                }

                for (; ((elem_idx >= ele_start) && (elem_idx < ele_stop)); elem_idx+=increm){
                        if (flag_monitor==2){
                            ParticlesMonitor_track_local_particle(tbt_monitor, &lpart);
                        }
                        if (offset_multi_element_monitor >= 0){
                            MultiElementMonitor_track_local_particle(
                                tbt_multi_elem_monitor, &lpart);
                        }

                        // Get the pointer to and the type id of the `elem_idx`th
                        // element in `element_ref_data.elements`:
                          void* el = ElementRefData_member_elements(elem_ref_data, elem_idx);
                        int64_t elem_type = ElementRefData_typeid_elements(elem_ref_data, elem_idx);

                        switch(elem_type){
        

                        case 0:


                            Cavity_track_local_particle_with_transformations((CavityData) el, &lpart);
                            break;

                        case 1:


                            #ifdef XTRACK_GLOBAL_XY_LIMIT
                            global_aperture_check(&lpart);
                            #endif

                            

                            Drift_track_local_particle_with_transformations((DriftData) el, &lpart);
                            break;

                        case 2:


                            DriftSlice_track_local_particle_with_transformations((DriftSliceData) el, &lpart);
                            break;

                        case 3:


                            DriftSliceCavity_track_local_particle_with_transformations((DriftSliceCavityData) el, &lpart);
                            break;

                        case 4:


                            DriftSliceMultipole_track_local_particle_with_transformations((DriftSliceMultipoleData) el, &lpart);
                            break;

                        case 5:


                            DriftSliceQuadrupole_track_local_particle_with_transformations((DriftSliceQuadrupoleData) el, &lpart);
                            break;

                        case 6:


                            DriftSliceRBend_track_local_particle_with_transformations((DriftSliceRBendData) el, &lpart);
                            break;

                        case 7:


                            DriftSliceSextupole_track_local_particle_with_transformations((DriftSliceSextupoleData) el, &lpart);
                            break;

                        case 8:


                            Marker_track_local_particle_with_transformations((MarkerData) el, &lpart);
                            break;

                        case 9:


                            MultiElementMonitor_track_local_particle_with_transformations((MultiElementMonitorData) el, &lpart);
                            break;

                        case 10:


                            Multipole_track_local_particle_with_transformations((MultipoleData) el, &lpart);
                            break;

                        case 11:


                            ParticlesMonitor_track_local_particle_with_transformations((ParticlesMonitorData) el, &lpart);
                            break;

                        case 12:


                            Quadrupole_track_local_particle_with_transformations((QuadrupoleData) el, &lpart);
                            break;

                        case 13:


                            RBend_track_local_particle_with_transformations((RBendData) el, &lpart);
                            break;

                        case 14:


                            Sextupole_track_local_particle_with_transformations((SextupoleData) el, &lpart);
                            break;

                        case 15:


                            SplineBoris_track_local_particle_with_transformations((SplineBorisData) el, &lpart);
                            break;

                        case 16:


                            ThickSliceCavity_track_local_particle_with_transformations((ThickSliceCavityData) el, &lpart);
                            break;

                        case 17:


                            ThickSliceMultipole_track_local_particle_with_transformations((ThickSliceMultipoleData) el, &lpart);
                            break;

                        case 18:


                            ThickSliceQuadrupole_track_local_particle_with_transformations((ThickSliceQuadrupoleData) el, &lpart);
                            break;

                        case 19:


                            ThickSliceRBend_track_local_particle_with_transformations((ThickSliceRBendData) el, &lpart);
                            break;

                        case 20:


                            ThickSliceSextupole_track_local_particle_with_transformations((ThickSliceSextupoleData) el, &lpart);
                            break;

                        case 21:


                            ThinSliceCavity_track_local_particle_with_transformations((ThinSliceCavityData) el, &lpart);
                            break;

                        case 22:


                            ThinSliceMultipole_track_local_particle_with_transformations((ThinSliceMultipoleData) el, &lpart);
                            break;

                        case 23:


                            ThinSliceQuadrupole_track_local_particle_with_transformations((ThinSliceQuadrupoleData) el, &lpart);
                            break;

                        case 24:


                            ThinSliceQuadrupoleEntry_track_local_particle_with_transformations((ThinSliceQuadrupoleEntryData) el, &lpart);
                            break;

                        case 25:


                            ThinSliceQuadrupoleExit_track_local_particle_with_transformations((ThinSliceQuadrupoleExitData) el, &lpart);
                            break;

                        case 26:


                            ThinSliceRBend_track_local_particle_with_transformations((ThinSliceRBendData) el, &lpart);
                            break;

                        case 27:


                            ThinSliceRBendEntry_track_local_particle_with_transformations((ThinSliceRBendEntryData) el, &lpart);
                            break;

                        case 28:


                            ThinSliceRBendExit_track_local_particle_with_transformations((ThinSliceRBendExitData) el, &lpart);
                            break;

                        case 29:


                            ThinSliceSextupole_track_local_particle_with_transformations((ThinSliceSextupoleData) el, &lpart);
                            break;

                        case 30:


                            ThinSliceSextupoleEntry_track_local_particle_with_transformations((ThinSliceSextupoleEntryData) el, &lpart);
                            break;

                        case 31:


                            ThinSliceSextupoleExit_track_local_particle_with_transformations((ThinSliceSextupoleExitData) el, &lpart);
                            break;

                        } //switch

                    // Setting the below flag will break particle losses
                    #ifndef DANGER_SKIP_ACTIVE_CHECK_AND_SWAPS

                    isactive = check_is_active(&lpart);
                    if (!isactive){
                        break;
                    }

                    if (LocalParticle_check_track_flag(&lpart, XS_FLAG_BACKTRACK)) {
                        increment_at_element(&lpart, -1);
                    } else {
                        increment_at_element(&lpart, 1);
                    }

                    #endif //DANGER_SKIP_ACTIVE_CHECK_AND_SWAPS

                } // for elements

                if (flag_monitor==2){
                    // End of turn (element-by-element mode)
                    ParticlesMonitor_track_local_particle(tbt_monitor, &lpart);
                }

                if (LocalParticle_check_track_flag(&lpart, XS_FLAG_BACKTRACK)) {
                    if (flag_monitor==1){
                        ParticlesMonitor_track_local_particle(tbt_monitor, &lpart);
                    }
                }
                else if (flag_end_turn_actions>0){
                    if (isactive){
                        increment_at_turn(&lpart, flag_reset_s_at_end_turn);
                    }
                }
            } // for turns

            LocalParticle_to_Particles(&lpart, particles, part_id, 1);

            }// if partid
            } //only_for_context cpu_openmp

            // On OpenMP we want to additionally by default reorganize all
            // the particles.
            #ifndef XT_OMP_SKIP_REORGANIZE                             //only_for_context cpu_openmp
            LocalParticle lpart;                                       //only_for_context cpu_openmp
            lpart.io_buffer = io_buffer;                               //only_for_context cpu_openmp
            Particles_to_LocalParticle(particles, &lpart, 0, capacity);//only_for_context cpu_openmp
            check_is_active(&lpart);                                   //only_for_context cpu_openmp
            count_reorganized_particles(&lpart);                       //only_for_context cpu_openmp
            LocalParticle_to_Particles(&lpart, particles, 0, capacity);//only_for_context cpu_openmp
            #endif                                                     //only_for_context cpu_openmp
        }//kernel
        
                void xo_omp_set_num_threads(int num_threads) {
                    omp_set_num_threads(num_threads);
                }

                int xo_omp_get_max_threads(void) {
                    return omp_get_max_threads();
                }
                

